-- Insert notes
INSERT INTO notes (id, title, content, tags, is_pinned, color, created_at, updated_at) VALUES
  ('note_welcome_001', 'Welcome to Notes RAG', 'This is a RAG (Retrieval-Augmented Generation) application built with Next.js 16, OpenAI, and PostgreSQL. You can create notes and chat with an AI assistant that searches through your notes using semantic search.', '{welcome,intro}', true, '#dbeafe', now(), now());
INSERT INTO notes (id, title, content, tags, is_pinned, color, created_at, updated_at) VALUES
  ('note_features_002', 'Key Features', 'The app includes: semantic search using OpenAI embeddings, vector similarity with pgvector, React Flow visualization of search results, note management with tags and colors, and streaming AI responses with tool calling.', '{features,technical}', true, '#fef3c7', now(), now());
INSERT INTO notes (id, title, content, tags, is_pinned, color, created_at, updated_at) VALUES
  ('note_tech_003', 'Tech Stack', 'Built with Next.js 16 App Router, TypeScript, Vercel AI SDK, OpenAI GPT-4 and embeddings, PostgreSQL with pgvector extension, Drizzle ORM, shadcn-ui components, TailwindCSS, and Vitest for testing.', '{tech,stack}', false, '#fce7f3', now(), now());

-- Insert resources
INSERT INTO resources (id, content, created_at, updated_at) VALUES
  ('resource_rag_001', 'RAG (Retrieval-Augmented Generation) is a technique that enhances LLM responses by retrieving relevant information from a knowledge base before generating answers. This allows the AI to provide accurate, context-specific responses based on your data.', now(), now());
INSERT INTO resources (id, content, created_at, updated_at) VALUES
  ('resource_vector_002', 'Vector embeddings are numerical representations of text that capture semantic meaning. Similar texts have similar embeddings, enabling semantic search. OpenAI text-embedding-ada-002 produces 1536-dimensional vectors.', now(), now());

